package firewall

import (
	"context"
	"strings"
	"testing"

	"github.com/litevirt/litevirt/internal/corrosion"
	"github.com/litevirt/litevirt/internal/testkit/golden"
)

// loadCompatPlan stores rows that load and apply on the build before the rule
// grammar (finding F-1) — each form checked with `nft -c` — written straight
// into the tables as a peer on that build replicates them, and loads them.
// testdata/render_compat_*.golden were generated by that build's renderer,
// so the golden test proves they render byte for byte as they did.
func loadCompatPlan(t *testing.T) Plan {
	t.Helper()
	ctx := context.Background()
	db := corrosion.NewTestClientT(t)
	if err := corrosion.InitSchema(ctx, db); err != nil {
		t.Fatalf("InitSchema: %v", err)
	}
	exec := func(sql string, args ...any) {
		t.Helper()
		if err := db.Execute(ctx, sql, args...); err != nil {
			t.Fatalf("insert: %v", err)
		}
	}
	const now = "2026-10-15T00:00:00Z"
	exec(`INSERT INTO ip_sets (id, name, cidrs, stack_name, created_at, updated_at)
		VALUES ('set-1', 'trusted', ?, '', ?, 1)`, `["10.0.0.0/24", "10.1.0.1-10.1.0.9", " 10.2.0.0/16"]`, now)
	n := 0
	cluster := func(dir, proto, port, cidr, action, comment string) {
		n++
		exec(`INSERT INTO cluster_firewall_rules
			(id, direction, proto, port_range, cidr, action, priority, comment, stack_name, created_at, updated_at)
			VALUES (?, ?, ?, ?, ?, ?, ?, ?, '', ?, 1)`,
			"c"+string(rune('a'+n)), dir, proto, port, cidr, action, n*10, comment, now)
	}
	cluster("ingress", "TCP", "{ 80, 443 }", "", "accept", strings.Repeat("c", 127))
	cluster("ingress", "tcp", "!=22", "10.0.0.1-10.0.0.9", "drop", strings.Repeat("d", 121))
	cluster("ingress", "tcp", "< 1024", "!= 10.0.0.0/8", "reject", "")
	cluster("ingress", "ESP", "", "", "accept", "")
	cluster("ingress", "udp", "8000 - 9000", "@trusted", "ACCEPT", "")
	cluster("ingress", "esp", "22 never written", "", "accept", "") // the port of an esp rule is not rendered
	cluster("", "tcp", "22", "", "", "")                            // compose rule with no direction or action
	cluster("in", "tcp", "3306", "", "drop", `a\b`)                 // any non-egress direction is ingress
	cluster("egress", "tcp", "ssh", " 192.0.2.0/24", "drop", "a\nb")
	cluster("ingress", "tcp", "{ 22, 2222 }", "!=@trusted", "drop", "")
	cluster("egress", "udp", "53", "gw.example.com", "accept", "")
	cluster("ingress", "!= tcp", "", "", "drop", "it's")
	cluster("ingress", "{ tcp, udp }", "", "198.51.100.0/24", "accept", "")
	cluster("ingress", "tcp", "8443", "", "accept", "per ticket #42; see wiki { x }") // quoted: # ; { } are text
	exec(`INSERT INTO host_firewall_rules
		(id, host_name, direction, proto, port_range, cidr, action, priority, comment, stack_name, created_at, updated_at)
		VALUES ('h1', 'host-a', 'EGRESS', 'Udp', 'eq 123', '{ 10.0.0.1, 10.0.0.2 }', 'Drop', 10, '', '', ?, 1)`, now)
	if err := corrosion.InsertSecurityGroup(ctx, db, corrosion.SecurityGroup{ID: "sg-1", Name: "web"}); err != nil {
		t.Fatal(err)
	}
	exec(`INSERT INTO sg_rules (id, sg_id, direction, proto, port_range, cidr, action, priority, created_at, updated_at)
		VALUES ('s1', 'sg-1', 'ingress', 'TCP', '{ 8080, 8443 }', '@trusted', 'accept', 10, ?, 1),
		       ('s2', 'sg-1', 'ingress', 'tcp', '1-1023', '', 'drop', 20, ?, 1)`, now, now)

	plan, err := CorrosionPlanLoader(db, "host-a", Plan{}, LoaderOptions{})(ctx)
	if err != nil {
		t.Fatalf("loader: %v", err)
	}
	return plan
}

// TestRenderCompatGolden: rows that apply today render byte for byte as they
// did before the rule grammar, in the inet table and in the per-NIC table of
// both modes.
func TestRenderCompatGolden(t *testing.T) {
	plan := loadCompatPlan(t)
	for _, mode := range []string{NICModeEnforce, NICModeObserve} {
		p := plan
		p.NICMode = mode
		p.NICs = []NICBinding{{NICDev: "tap0", VMName: "vm", SecurityGroups: []string{"web"}}}
		got, err := Render(p)
		if err != nil {
			t.Fatalf("%s: Render refused rows that apply today: %v", mode, err)
		}
		golden.Assert(t, "testdata/render_compat_"+mode+".golden", got)
	}
}
